-- 10. COMPONENT FAULTS
--    3 row(s).
-- ════════════════════════════════════════════════════════════

with
  engine_lookup as (
    select id, code, power_kw from catalog_engines
    where (code, power_kw) in (('i3-60Ah', 125), ('i3-94Ah', 125))
  ),
  engine_faults (target_code, target_power_kw, fault, severity) as (
    values
      ('i3-60Ah'::text, 125::integer, 'High-voltage electronics (EME) / charging-unit (KLE) failure — no charging or drive; expensive out of warranty.'::text, 'critical'::text),
      ('i3-94Ah'::text, 125::integer, '12 V battery and its charging fault messages; the car won''t wake up.'::text, 'minor'::text)
  )
insert into catalog_component_faults (component_type, engine_id, fault, severity)
select 'engine', e.id, f.fault, f.severity
from engine_faults f
join engine_lookup e on e.code = f.target_code and e.power_kw = f.target_power_kw
where not exists (
  select 1 from catalog_component_faults ccf where ccf.engine_id = e.id and ccf.fault = f.fault
);

with
  phase_lookup as (
    select cp.id, cp.phase_label
    from catalog_phases cp
    join catalog_models cm on cm.id = cp.model_id
    join catalog_brands cb on cb.id = cm.brand_id
    where cb.name = 'BMW' and cm.name = 'i3' and cp.generation_code = 'I01'
  ),
  vehicle_faults (phase_label, fault, severity, category) as (
    values
      ('Pre-facelift'::text, 'Front suspension (lower arm bushes) knocks; steering rack noise.'::text, 'minor'::text, 'suspension'::text)
  )
insert into catalog_component_faults (component_type, phase_id, fault, severity, category)
select 'vehicle', p.id, f.fault, f.severity, f.category
from vehicle_faults f
join phase_lookup p on p.phase_label = f.phase_label
where not exists (
  select 1 from catalog_component_faults ccf where ccf.phase_id = p.id and ccf.fault = f.fault
);

-- ════════════════════════════════════════════════════════════
-- 11. POST-CONDITION ASSERTIONS
--    Asserts exactly the expected phase and config counts for this generation_code exist live -- catches a silent guard false-positive (e.g. the phases-guard bug: matching another generation's same-labeled phase) instead of leaving it undetected.
-- ════════════════════════════════════════════════════════════

do $$
declare
  phase_n integer;
  config_n integer;
begin
  select count(*) into phase_n
  from catalog_phases cp
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'BMW' and cm.name = 'i3' and cp.generation_code = 'I01';
  if phase_n <> 2 then
    raise exception 'Expected 2 phase(s) for BMW i3 (I01), found % -- a phase guard may have false-positived against another generation.', phase_n;
  end if;

  select count(*) into config_n
  from catalog_vehicle_configurations cvc
  join catalog_phases cp on cp.id = cvc.phase_id
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'BMW' and cm.name = 'i3' and cp.generation_code = 'I01';
  if config_n <> 6 then
    raise exception 'Expected 6 config(s) for BMW i3 (I01), found %.', config_n;
  end if;
end $$;
